let escolas = $input.all().map(i => i.json);
if (escolas.length === 1 && Array.isArray(escolas[0].content)) escolas = escolas[0].content; // caso a API seja paginada
const nomes = escolas.map(e => e.nome).filter(Boolean);
const cfg = $('Config').first().json;

// Campos iguais aos formulários do site (Escolas, Endereços, Avaliações de Qualidade, Cursos, Alunos)
const modelo = {
  escolas: [
    {
      escola: { nome: "string", tipo: "Pública, Estadual, Municipal, Técnica, Privada ou Federal", telefone: "(XX) XXXXX-XXXX", email: "string" },
      endereco: { cep: "00000-000", logradouro: "string", numero: "string", bairro: "string", cidade: "string", estado: "UF" },
      avaliacao: { nota: "inteiro de 1 a 5", comentario: "string", dataAvaliacao: "AAAA-MM-DD" },
      curso: { nome: "string", descricao: "string curta", cargaHoraria: "inteiro em horas" },
      avaliacaoCurso: { nota: "número de 0 a 10, pode ter uma casa decimal", observacao: "string", dataAvaliacao: "AAAA-MM-DD" },
      professores: [ { nome: "string", email: "string", telefone: "(XX) XXXXX-XXXX", especialidade: "disciplina, ex: Matemática", biografia: "formação e experiência, 1 frase" } ],
      alunos: [
        { area: "urbana ou rural", distanciaEscola: "número em km, ex: 5.2", tipoTransporte: "a_pe, transporte_escolar, transporte_publico ou proprio", tempoDeslocamentoMinutos: "inteiro" }
      ]
    }
  ]
};

const prompt = `Você gera dados fictícios para um sistema brasileiro de avaliação de escolas.

Escolas já cadastradas (NÃO repita nem copie estes nomes):
${nomes.length ? nomes.map(n => '- ' + n).join('\n') : '(nenhuma)'}

Crie exatamente ${cfg.qtdEscolas} escolas NOVAS, com nomes diferentes dos acima e entre si, no mesmo estilo dos nomes existentes.
Para cada escola gere: os dados da escola, 1 endereço realista (cidade brasileira real), 1 avaliação de qualidade (nota inteira de 1 a 5), 1 curso oferecido pela escola, 1 avaliação desse curso (nota de 0 a 10), exatamente ${cfg.qtdProfessores} professores (nome brasileiro, especialidade e biografia curta) e exatamente ${cfg.qtdAlunos} alunos. Os alunos NÃO têm nome: gere só os indicadores de deslocamento até a escola, de forma coerente (aluno de área rural tende a ter distância e tempo maiores).

Responda SOMENTE com JSON válido, neste formato:
${JSON.stringify(modelo, null, 2)}`;

return [{ json: { prompt, nomes } }];

const resp = $input.first().json;

// Aceita os dois formatos: nó Gemini do n8n ({ text }) ou chamada HTTP direta ({ candidates })
let bruto = resp.text ?? resp.output ?? resp.response ?? resp.content;
if (bruto === undefined) {
  bruto = (resp.candidates?.[0]?.content?.parts || []).map(p => p.text || '').join('');
}

let dados;
if (typeof bruto === 'string') {
  const texto = bruto.replace(/```json|```/g, '').trim();
  if (!texto) throw new Error('Gemini não retornou conteúdo: ' + JSON.stringify(resp).slice(0, 1500));
  try {
    dados = JSON.parse(texto);
  } catch (e) {
    throw new Error('JSON do Gemini inválido ou cortado (' + e.message + '). Final da resposta: ' + texto.slice(-300));
  }
} else {
  dados = bruto;
}

const lista = Array.isArray(dados) ? dados : dados?.escolas;
if (!Array.isArray(lista)) throw new Error('Formato inesperado, sem a lista "escolas": ' + JSON.stringify(dados).slice(0, 500));

const cfg = $('Config').first().json;
const existentes = new Set($('Montar Prompt').first().json.nomes.map(n => n.trim().toLowerCase()));

const TIPOS = ['Pública', 'Estadual', 'Municipal', 'Técnica', 'Privada', 'Federal'];
const TRANSPORTES = ['a_pe', 'transporte_escolar', 'transporte_publico', 'proprio'];

const normalizar = (e) => {
  const nota = Math.round(Number(e.avaliacao?.nota));
  return {
    escola: { ...e.escola, tipo: TIPOS.includes(e.escola.tipo) ? e.escola.tipo : 'Pública' },
    endereco: e.endereco || {},
    avaliacao: {
      nota: Math.min(5, Math.max(1, Number.isFinite(nota) ? nota : 3)),
      comentario: e.avaliacao?.comentario || null,
      dataAvaliacao: e.avaliacao?.dataAvaliacao || null,
    },
    curso: {
      nome: e.curso?.nome || 'Ensino Regular',
      descricao: e.curso?.descricao || '',
      cargaHoraria: Math.round(Number(e.curso?.cargaHoraria)) || null,
    },
    avaliacaoCurso: {
      nota: Math.min(10, Math.max(0, Math.round((Number(e.avaliacaoCurso?.nota) || 7) * 10) / 10)),
      observacao: e.avaliacaoCurso?.observacao || null,
      dataAvaliacao: e.avaliacaoCurso?.dataAvaliacao || null,
    },
    professores: (e.professores || []).filter(p => p?.nome).slice(0, cfg.qtdProfessores).map(p => ({
      nome: p.nome,
      email: p.email || null,
      telefone: p.telefone || null,
      especialidade: p.especialidade || null,
      biografia: p.biografia || null,
    })),
    alunos: (e.alunos || []).slice(0, cfg.qtdAlunos).map(a => ({
      area: String(a.area || '').toLowerCase() === 'rural' ? 'rural' : 'urbana',
      distanciaEscola: Math.round((Number(a.distanciaEscola) || 0) * 100) / 100,
      tipoTransporte: TRANSPORTES.includes(a.tipoTransporte) ? a.tipoTransporte : 'a_pe',
      tempoDeslocamentoMinutos: Math.round(Number(a.tempoDeslocamentoMinutos)) || 0,
    })),
  };
};

return lista
  .filter(e => e?.escola?.nome && !existentes.has(e.escola.nome.trim().toLowerCase()))
  .slice(0, cfg.qtdEscolas)
  .map(e => ({ json: normalizar(e) }));

const escolas = $('Extrair Escolas').all();
const escolasCriadas = $('Criar Escola').all();
const cursosCriados = $('Criar Curso').all();
const out = [];
escolas.forEach((e, i) => {
  const escolaId = escolasCriadas[i].json.id;
  const cursoId = cursosCriados[i].json.id;
  (e.json.alunos || []).forEach(a => {
    out.push({ json: { ...a, escola: { id: escolaId }, curso: { id: cursoId } } });
  });
});
return out;

const todos = (nome) => { try { return $(nome).all(); } catch (e) { return []; } }; // nó que não rodou (ramo não executado)
const v = $('Validar Escolas').first().json;

const MAPA = { 'endereço': 'endereco', 'aluno': 'aluno', 'avaliação de qualidade': 'avaliacao' };
const feitos = {};
const registros = { enderecos: 0, avaliacoes: 0, alunos: 0 };
for (const i of todos('Montar Reparos')) {
  const { escolaId, tipo } = i.json;
  (feitos[String(escolaId)] ||= new Set()).add(tipo);
  if (tipo === 'endereco') registros.enderecos++;
  if (tipo === 'avaliacao') registros.avaliacoes++;
  if (tipo === 'aluno') registros.alunos++;
}
const restantes = v.pendencias.filter(p => !p.falta.every(f => feitos[String(p.id)]?.has(MAPA[f])));

return [{ json: {
  escolasCriadas: todos('Criar Escola').length,
  enderecosCriados: todos('Criar Endereço').length,
  avaliacoesCriadas: todos('Criar Avaliação').length,
  cursosCriados: todos('Criar Curso').length,
  avaliacoesCursoCriadas: todos('Criar Avaliação do Curso').length,
  alunosCriados: todos('Criar Aluno').length,
  professoresCriados: todos('Criar Professor').length,
  validacao: { totalEscolas: v.totalEscolas, existePendencia: v.existePendencia, pendencias: v.pendencias },
  reparo: {
    executado: v.existePendencia,
    escolasReparadas: v.pendencias.length - restantes.length,
    registrosCriados: registros,
    restantes
  }
} }];

const escolas = $('Extrair Escolas').all();
const escolasCriadas = $('Criar Escola').all();
const out = [];
escolas.forEach((e, i) => {
  const escolaId = escolasCriadas[i].json.id;
  (e.json.professores || []).forEach(p => out.push({ json: { escolaId, payload: p } }));
});
return out;

// Lê as listas completas da API e cruza por escola.id
const lista = (nome) => {
  let itens = $(nome).all().map(i => i.json);
  if (itens.length === 1 && Array.isArray(itens[0].content)) itens = itens[0].content; // caso a API seja paginada
  return itens.filter(i => i && Object.keys(i).length > 0);
};
const idDaEscola = (r) => r?.escola?.id ?? r?.escolaId ?? null;
const idsComRegistro = (nome) =>
  new Set(lista(nome).map(idDaEscola).filter(v => v !== null && v !== undefined).map(String));

const escolas = lista('Verificar Escolas').filter(e => e.id !== undefined);
if (escolas.length === 0) throw new Error('GET /api/escolas não retornou nenhuma escola.');

const comEndereco = idsComRegistro('Verificar Endereços');
const comAluno = idsComRegistro('Verificar Alunos');
const comAvaliacao = idsComRegistro('Verificar Avaliações');
const criadasAgora = new Set($('Criar Escola').all().map(i => String(i.json.id)));
const cursoPorEscola = {};
for (const c of lista('Verificar Cursos')) {
  const id = idDaEscola(c);
  if (id !== null && id !== undefined && cursoPorEscola[String(id)] === undefined) cursoPorEscola[String(id)] = c.id;
}

const pendencias = [];
for (const e of escolas) {
  const id = String(e.id);
  const falta = [];
  if (!comEndereco.has(id)) falta.push('endereço');
  if (!comAluno.has(id)) falta.push('aluno');
  if (!comAvaliacao.has(id)) falta.push('avaliação de qualidade');
  if (falta.length) pendencias.push({ id: e.id, nome: e.nome, tipo: e.tipo, falta, nova: criadasAgora.has(id), cursoId: cursoPorEscola[id] ?? null });
}

return [{ json: { totalEscolas: escolas.length, existePendencia: pendencias.length > 0, pendencias } }];

const v = $('Validar Escolas').first().json;
const cfg = $('Config').first().json;
const pendencias = v.pendencias.slice(0, cfg.maxReparos); // limite por execução, para não estourar a IA
const itens = pendencias.map(p => ({ id: p.id, nome: p.nome, tipo: p.tipo, precisa: p.falta }));

const modelo = {
  reparos: [
    {
      id: "id da escola, igual ao informado",
      endereco: { cep: "00000-000", logradouro: "string", numero: "string", bairro: "string", cidade: "string", estado: "UF" },
      avaliacao: { nota: "inteiro de 1 a 5", comentario: "string", dataAvaliacao: "AAAA-MM-DD" },
      alunos: [
        { area: "urbana ou rural", distanciaEscola: "número em km, ex: 5.2", tipoTransporte: "a_pe, transporte_escolar, transporte_publico ou proprio", tempoDeslocamentoMinutos: "inteiro" }
      ]
    }
  ]
};

const prompt = `Você completa cadastros incompletos de um sistema brasileiro de avaliação de escolas.

Para cada escola abaixo, gere SOMENTE o que está listado em "precisa" e omita as demais chaves:
- "endereço": 1 endereço realista na cidade indicada pelo nome da escola (rua, número, bairro, CEP e UF coerentes);
- "avaliação de qualidade": 1 avaliação com nota inteira de 1 a 5, comentário curto e data recente;
- "aluno": exatamente ${cfg.qtdAlunos} alunos. Alunos NÃO têm nome: gere só os indicadores de deslocamento até a escola, de forma coerente (área rural tende a ter distância e tempo maiores).

Escolas:
${JSON.stringify(itens, null, 2)}

Responda SOMENTE com JSON válido, neste formato (use apenas as chaves necessárias para cada escola e copie o "id" informado):
${JSON.stringify(modelo, null, 2)}`;

return [{ json: { prompt, pendencias } }];

const resp = $input.first().json;

let bruto = resp.text ?? resp.output ?? resp.response ?? resp.content;
if (bruto === undefined) {
  bruto = (resp.candidates?.[0]?.content?.parts || []).map(p => p.text || '').join('');
}
let dados;
if (typeof bruto === 'string') {
  const texto = bruto.replace(/```json|```/g, '').trim();
  if (!texto) throw new Error('Gemini (reparo) não retornou conteúdo: ' + JSON.stringify(resp).slice(0, 1500));
  try {
    dados = JSON.parse(texto);
  } catch (e) {
    throw new Error('JSON do Gemini (reparo) inválido ou cortado (' + e.message + '). Final da resposta: ' + texto.slice(-300));
  }
} else {
  dados = bruto;
}
const lista = Array.isArray(dados) ? dados : dados?.reparos;
if (!Array.isArray(lista)) throw new Error('Formato inesperado, sem a lista "reparos": ' + JSON.stringify(dados).slice(0, 500));

const cfg = $('Config').first().json;
const pendencias = $('Montar Prompt Reparo').first().json.pendencias;
const TRANSPORTES = ['a_pe', 'transporte_escolar', 'transporte_publico', 'proprio'];

const out = [];
for (const p of pendencias) {
  const r = lista.find(x => String(x?.id) === String(p.id)) || lista.find(x => x?.nome === p.nome);
  if (!r) continue;
  const escolaId = p.id;

  if (p.falta.includes('endereço') && r.endereco?.logradouro) {
    const e = r.endereco;
    out.push({ json: { tipo: 'endereco', escolaId, payload: {
      cep: e.cep ?? '', logradouro: e.logradouro, numero: e.numero ?? '', bairro: e.bairro ?? '',
      cidade: e.cidade ?? '', estado: e.estado ?? '', escola: { id: escolaId } } } });
  }
  if (p.falta.includes('avaliação de qualidade') && r.avaliacao) {
    const nota = Math.round(Number(r.avaliacao.nota));
    out.push({ json: { tipo: 'avaliacao', escolaId, payload: {
      nota: Math.min(5, Math.max(1, Number.isFinite(nota) ? nota : 3)),
      comentario: r.avaliacao.comentario || null,
      dataAvaliacao: r.avaliacao.dataAvaliacao || null } } });
  }
  if (p.falta.includes('aluno') && Array.isArray(r.alunos)) {
    r.alunos.slice(0, cfg.qtdAlunos).forEach(a => out.push({ json: { tipo: 'aluno', escolaId, payload: {
      area: String(a.area || '').toLowerCase() === 'rural' ? 'rural' : 'urbana',
      distanciaEscola: Math.round((Number(a.distanciaEscola) || 0) * 100) / 100,
      tipoTransporte: TRANSPORTES.includes(a.tipoTransporte) ? a.tipoTransporte : 'a_pe',
      tempoDeslocamentoMinutos: Math.round(Number(a.tempoDeslocamentoMinutos)) || 0,
      escola: { id: escolaId },
      curso: p.cursoId ? { id: p.cursoId } : null } } }));
  }
}
if (out.length === 0) throw new Error('O Gemini não devolveu dados utilizáveis para as escolas pendentes.');
return out;
